import { test, expect, secret } from '../../src/fixtures.ts';

test('Log in, add a payee and see a success message', async ({ page }) => {
  await test.step('Open the app', async () => {
    await page.goto('/');
  });

  await test.step('Log in', async () => {
    await page.getByLabel('Username', { exact: true }).fill(secret('username'));
    await page.getByLabel('Password', { exact: true }).fill(secret('password'));
    await page.getByRole('button', { name: 'Sign in', exact: true }).click();
  });

  await test.step('Fill in the payee', async () => {
    await page.getByLabel('Payee name', { exact: true }).fill('Acme Utilities');
    await page.getByLabel('Account number', { exact: true }).fill('12345678');
    await page.getByLabel('Payee type', { exact: true }).selectOption({ label: 'Business' });
  });

  await test.step('Submit', async () => {
    await page.getByRole('button', { name: 'Add payee', exact: true }).click();
  });

  await test.step('Success message is shown', async () => {
    await expect(page.getByRole('region', { name: 'Add a payee', exact: true }).getByRole('status')).toContainText('Payee Acme Utilities added');
  });
});
